test.each([0, 600])(
  "buildConfig() accepts a reorg window of %s seconds",
  (reorgWindow) => {
    const config = createConfig({
      chains: {
        mainnet: {
          id: 1,
          rpc: `http://127.0.0.1:8545/${TEST_POOL_ID}`,
          reorgWindow,
        },
      },
      blocks: { b: { chain: "mainnet" } },
    });

    const { chains } = buildConfig({ common: context.common, config });

    expect(chains[0]!.reorgWindow).toBe(reorgWindow);
  },
)

test.each([-1, 1.5, 601, Number.NaN])(
  "buildConfig() rejects an invalid reorg window of %s",
  (reorgWindow) => {
    const config = createConfig({
      chains: {
        mainnet: {
          id: 1,
          rpc: `http://127.0.0.1:8545/${TEST_POOL_ID}`,
          reorgWindow,
        },
      },
      blocks: { b: { chain: "mainnet" } },
    });

    expect(() => buildConfig({ common: context.common, config })).toThrow(
      `Invalid 'reorgWindow' for chain 'mainnet'. Expected an integer between 0 and 600 seconds, got ${reorgWindow}.`,
    );
  },
)

test.each(["contract start block", "crash recovery"])(
  "syncBlockData() with log factory starting earlier than %s",
  async (scenario) => {
    // Note: One block per "eth_getLogs" page puts the factory's first page before
    // the contract's start block.
    const chain = {
      ...getChain({ cacheRpcRequests: false }),
      ethGetLogsBlockRange: 1,
    };
    const rpc = createRpc({ chain, common: context.common });

    const { address } = await deployFactory({ sender: ALICE });
    const { address: pair } = await createPair({
      factory: address,
      sender: ALICE,
    });
    await swapPair({
      pair,
      amount0Out: 1n,
      amount1Out: 1n,
      to: ALICE,
      sender: ALICE,
    });

    const { eventCallbacks } = getPairWithFactoryIndexingBuild({ address });
    const filter = eventCallbacks[0]!.filter as LogFilter;
    filter.fromBlock = scenario === "contract start block" ? 3 : 0;

    const historicalSync = createInMemoryHistoricalSync({
      common: context.common,
      chain,
      rpc,
      childAddress: setupChildAddresses(eventCallbacks),
    });
    const requiredIntervals = getRequiredIntervalsWithFilters({
      interval: [0, 3],
      filters: [filter],
      cachedIntervals: setupCachedIntervals(eventCallbacks),
    });
    // Crash recovery can move the required interval beyond the configured start.
    requiredIntervals.intervals[0]!.interval[0] = 3;
    expect(requiredIntervals.factoryIntervals[0]!.interval).toStrictEqual([
      0, 3,
    ]);

    const blockData = await drainAsyncGenerator(
      historicalSync.syncBlockData({
        requiredIntervals: requiredIntervals.intervals,
        requiredFactoryIntervals: requiredIntervals.factoryIntervals,
      }),
    );

    expect(blockData.map(({ cursor }) => cursor)).toStrictEqual([3]);
    expect(blockData.flatMap(({ logs }) => logs)).toHaveLength(1);
    expect(blockData[0]!.logs[0]!.address).toBe(toLowerCase(pair));
  },
)

test.each([143, 10143, 43114, 43113])(
  "sync() skips logs bloom warning on async-execution chain %i",
  async (chainId) => {
    const { common } = context;
    await setupDatabaseServices();

    const chain = { ...getChain({ reorgWindow: 2 }), id: chainId };
    const rpc = createRpc({ common, chain });

    const { address } = await deployErc20({ sender: ALICE });
    await mintErc20({
      erc20: address,
      to: ALICE,
      amount: parseEther("1"),
      sender: ALICE,
    });

    const { eventCallbacks } = getErc20IndexingBuild({ address });

    const finalizedBlock = await eth_getBlockByNumber(rpc, ["0x1", true]);
    const block = await eth_getBlockByNumber(rpc, ["0x2", true]);
    const warnSpy = vi.spyOn(common.logger, "warn");

    const isBloomWarning = () =>
      warnSpy.mock.calls.some(
        ([log]) =>
          log.msg ===
          "Detected inconsistent RPC responses. Log not found in block.logsBloom.",
      );

    await drainAsyncGenerator(
      createRealtimeSync({
        common,
        chain,
        rpc,
        eventCallbacks,
        syncProgress: { finalized: finalizedBlock },
        childAddresses: new Map(),
      }).sync({
        ...block,
        logsBloom: zeroLogsBloom,
      }),
    );

    expect(isBloomWarning()).toBe(false);

    await drainAsyncGenerator(
      createRealtimeSync({
        common,
        chain: { ...chain, id: 1 },
        rpc,
        eventCallbacks,
        syncProgress: { finalized: finalizedBlock },
        childAddresses: new Map(),
      }).sync({ ...block, logsBloom: zeroLogsBloom }),
    );

    expect(isBloomWarning()).toBe(true);
  },
)

